def _check_success(self):
    """
    Check if the door manipulation task is successful.

    Returns:
        bool: True if the task is successful, False otherwise.
    """
    if self.behavior == "open":
        return self.fxtr.is_open(env=self)
    elif self.behavior == "close":
        return self.fxtr.is_closed(env=self)

def _setup_kitchen_references(self):
    """
    Setup the kitchen references for the stove knob tasks
    This includes the stove and the stove knob to manipulate, and the burner to place the cookware on.
    """
    super()._setup_kitchen_references()
    self.stove = self.get_fixture(FixtureType.STOVE)
    if "task_refs" in self._ep_meta:
        self.knob = self._ep_meta["task_refs"]["knob"]
        self.cookware_burner = self._ep_meta["task_refs"]["cookware_burner"]
    else:
        valid_knobs = [
            k for (k, v) in self.stove.knob_joints.items() if v is not None
        ]
        if self.knob_id == "random":
            self.knob = self.rng.choice(list(valid_knobs))
        else:
            assert self.knob_id in valid_knobs
            self.knob = self.knob
        self.cookware_burner = (
            self.knob
            if self.rng.uniform() <= 0.50
            else self.rng.choice(valid_knobs)
        )
    self.init_robot_base_ref = self.stove

def _setup_kitchen_references(self):
    super()._setup_kitchen_references()
    self.drawer = self.register_fixture_ref(
        "drawer", dict(id=FixtureType.TOP_DRAWER)
    )
    self.counter = self.register_fixture_ref(
        "counter", dict(id=FixtureType.COUNTER, ref=self.drawer)
    )
    self.init_robot_base_ref = self.drawer

def _check_success(self):
    on_counter = OU.check_obj_any_counter_contact(self, "obj")
    return on_counter and OU.gripper_obj_far(self, "obj")

def _check_success(self):
    """
    Check if the drawer manipulation task is successful.

    Returns:
        bool: True if the task is successful, False otherwise.
    """
    door_state = self.drawer.get_door_state(env=self)

    success = True
    for joint_p in door_state.values():
        if self.behavior == "open":
            if joint_p < 0.95:
                success = False
                break
        elif self.behavior == "close":
            if joint_p > 0.05:
                success = False
                break

    return success

def check_obj_any_counter_contact(env, obj_name):
    from robocasa.models.fixtures import Counter

    """
    check if the object is in contact with any counter fixture in the environment.
    """
    for fixture in env.fixtures.values():
        if isinstance(fixture, Counter):
            if check_obj_fixture_contact(env, obj_name, fixture):
                return True
    return False

def is_open(self, env, joint_names=None, th=0.90):
    if joint_names is None:
        joint_names = self.door_joint_names
    joint_state = self.get_joint_state(env, joint_names)
    for j_name in joint_names:
        assert j_name in joint_state
        norm_qpos = joint_state[j_name]
        if norm_qpos < th:
            return False
    return True

def is_closed(self, env, joint_names=None, th=0.005):
    if joint_names is None:
        joint_names = self.door_joint_names
    joint_state = self.get_joint_state(env, joint_names)
    for j_name in joint_names:
        assert j_name in joint_state
        norm_qpos = joint_state[j_name]
        if norm_qpos > th:
            return False
    return True

def update_state(self, env):
    """
    If the microwave is open, the state is set to off. Otherwise, if the gripper
    is pressing the start button, the microwave will stay/turn on. If the gripper is
    pressing the stop button, the microwave will stay/turn off.

    Args:
        env (MujocoEnv): The environment to check the state of the microwave in

    """
    start_button_pressed = env.check_contact(
        env.robots[0].gripper["right"], "{}_start_button".format(self.name)
    )
    stop_button_pressed = env.check_contact(
        env.robots[0].gripper["right"], "{}_stop_button".format(self.name)
    )

    door_open = self.is_open(env)
    if door_open:
        self._turned_on = False
    else:
        if self._turned_on is True and stop_button_pressed:
            self._turned_on = False
        elif self._turned_on is False and start_button_pressed:
            self._turned_on = True

def update_state(self, env):
    """
    Update the state of the stand mixer
    """
    # read power button
    btn = self._joint_names["button_head_lock"]
    if btn in env.sim.model.joint_names:
        pos = self.get_joint_state(env, [btn])[btn]
        if pos > 0.75:
            self._button_head_lock = True

    # sync positions back into internal values
    mapping = {
        "_speed_dial_knob_value": "knob_speed",
        "_head_value": "head",
    }
    for attr, key in mapping.items():
        jn = self._joint_names[key]
        if jn in env.sim.model.joint_names:
            setattr(self, attr, self.get_joint_state(env, [jn])[jn])

def get_state(self, env):
    """
    Returns a dictionary representing the state of the stand mixer.
    """
    st = {}
    for name, jn in self._joint_names.items():
        if jn in env.sim.model.joint_names:
            st[name] = getattr(self, f"_{name}_value", None)
    return st

def terminal_messages(task: str, with_rationale: bool = False) -> list[dict[str, Any]]:
    if with_rationale:
        suffix = (
            "Provide one short, compact rationale followed by the score. Return exactly:\n"
            "Rationale: <rationale>\n\nScore: <1-5>"
        )
    else:
        suffix = "Do not provide a rationale. Return exactly:\nScore: <1-5>"
    user = (
        f"Task: {_compact(task)}\n\n"
        "Complete trajectory video:\n<video>\n\n"
        "Evaluate the terminal success of the task."
    )
    return _messages(f"{_TERMINAL_SYSTEM}\n{suffix}", user)
